cat > lib/refunds.js <<'EOF'
/**
 * Returns the refund in cents when a customer gets `percent` percent of
 * `totalCents` back. Rounds down to the whole cent, never to the nearest:
 * the payment provider refuses a refund above the remaining captured amount.
 */
export function computeRefund(totalCents, percent) {
  if (!Number.isInteger(totalCents) || totalCents < 0) {
    throw new Error(`Not an amount in cents: ${totalCents}`);
  }
  if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
    throw new Error(`Not a percentage between 0 and 100: ${percent}`);
  }
  return Math.floor((totalCents * percent) / 100);
}
EOF
cat > test/refunds.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { computeRefund } from '../lib/refunds.js';

test('refunds a whole percentage of the total', () => {
  assert.equal(computeRefund(10000, 25), 2500);
  assert.equal(computeRefund(10000, 100), 10000);
  assert.equal(computeRefund(10000, 0), 0);
});

test('rounds down to the whole cent', () => {
  assert.equal(computeRefund(999, 50), 499);
  assert.equal(computeRefund(1, 99), 0);
});

test('rejects invalid input', () => {
  assert.throws(() => computeRefund(10.5, 10));
  assert.throws(() => computeRefund(1000, 101));
  assert.throws(() => computeRefund(1000, -1));
});
EOF
